import React from "react";

const VisualizationButtons = () => (
  <div style={{ marginTop: "20px", display: "flex", gap: "10px" }}>
    <button style={{ padding: "10px", background: "black", color: "white" }}>Show Heatmap</button>
    <button style={{ padding: "10px", background: "black", color: "white" }}>Show Bar Graph</button>
    <button style={{ padding: "10px", background: "black", color: "white" }}>Show Histogram</button>
  </div>
);

export default VisualizationButtons;
